import type { Pool, PoolClient } from "pg";
import {
  PlatformSecurityEventSchema,
  PlatformSecurityEventWriteSchema,
  UuidV7Schema,
  uuidV7FromModule,
  type PlatformSecurityEvent,
  type PlatformSecurityEventWrite,
} from "@pos-platform/contracts";

/**
 * Persists identity security events into the existing identity.security_events
 * table. The caller must pass a PoolClient inside the same transaction as the
 * security state transition when atomicity is required.
 *
 * server_recorded_at is always generated by PostgreSQL, never accepted from the
 * caller. This repository intentionally has no update/delete API.
 */
export class PostgresPlatformSecurityEventRepository {
  constructor(private readonly pool: Pool) {}

  async append(eventInput: PlatformSecurityEventWrite, transaction?: PoolClient): Promise<PlatformSecurityEvent> {
    const eventId = uuidV7FromModule();
    UuidV7Schema.parse(eventInput.correlation_id);
    // Validate the write contract without inventing a server timestamp.
    // The persisted event is validated again using PostgreSQL's returned timestamp.
    PlatformSecurityEventWriteSchema.parse(eventInput);

    const executor = transaction ?? this.pool;
    const result = await executor.query<{
      user_id: string | null;
      session_id: string | null;
      tenant_id: string | null;
      event_code: string;
      result: string;
      reason_code: string | null;
      correlation_id: string;
      occurred_at: Date;
      server_recorded_at: Date;
    }>(
      `INSERT INTO identity.security_events (
         id, user_id, session_id, tenant_id, device_id, event_code, result,
         reason_code, correlation_id, occurred_at, server_recorded_at
       ) VALUES (
         $1, $2, $3, $4, NULL, $5, $6, $7, $8, $9::timestamptz, clock_timestamp()
       )
       RETURNING user_id::text, session_id::text, tenant_id::text, event_code, result,
                 reason_code, correlation_id::text, occurred_at, server_recorded_at`,
      [
        eventId,
        eventInput.user_id,
        eventInput.session_id,
        eventInput.tenant_id,
        eventInput.event_code,
        eventInput.result,
        eventInput.reason_code,
        eventInput.correlation_id,
        eventInput.occurred_at,
      ],
    );

    const row = result.rows[0];
    if (!row) throw new Error("PLATFORM_SECURITY_EVENT_INSERT_RETURNED_NO_ROW");
    return PlatformSecurityEventSchema.parse({
      user_id: row.user_id,
      session_id: row.session_id,
      tenant_id: row.tenant_id,
      event_code: row.event_code,
      result: row.result,
      reason_code: row.reason_code,
      correlation_id: row.correlation_id,
      occurred_at: row.occurred_at.toISOString(),
      server_recorded_at: row.server_recorded_at.toISOString(),
    });
  }
}
